class Solution:
    def minimizedMaximum(self, n: int, quantities: list[int]) -> int:
        lo, hi = 1, max(quantities)        # hi stores always suffice: one store per type
        while lo < hi:                     # O(log max(quantities)) iterations
            mid = (lo + hi) // 2           # candidate cap on products per store
            stores = sum((q + mid - 1) // mid for q in quantities)   # ceil(q / mid) stores per type, O(m)
            if stores <= n:
                hi = mid                   # cap is feasible: try a smaller one
            else:
                lo = mid + 1               # too many stores needed: raise the cap
        return lo

